(()=>{'use strict';let session=null,version=0,controller=null,story=null;const notice='For fun only — inspired by traditional palmistry, not a factual prediction.';const q=s=>document.querySelector(s);const section=document.createElement('section');section.id='fun-reading';section.className='reading section-pad fun-reading';section.innerHTML=`<p class="eyebrow">A LITTLE MAGIC / FOR FUN ONLY</p><h2>Your palmistry reading.<br><em>A little magic, for fun.</em></h2><p class="fun-intro">Explore love, relationships, marriage, career, and future possibilities through symbolic palmistry. For fun only; no factual predictions or calculated marriage ages.</p><div class="fun-notice">✦ For fun only — not a factual prediction.<br><small>විනෝදාස්වාදය සඳහා පමණි. සැබෑ අනාගත අනාවැකියක් නොවේ.</small></div><div id="fun-empty" class="compact-empty">Analyze both palms in the studio first. Then choose a theme and create your story. <a href="#scanner">Open the palm studio ↗</a></div><div id="fun-controls" hidden><label class="fun-theme">CHOOSE YOUR READING TOPICS<select id="fun-theme"><option value="full">Full reading — all topics</option><option value="relationships">Love & relationships</option><option value="marriage">Marriage & commitment</option><option value="career">Career & ambitions</option><option value="future">Future possibilities</option></select></label><details class="fun-manual"><summary>Optional: choose your own line symbols <span>+</span></summary><p>Look at your photograph and select shapes if you wish. These are manual storytelling choices, not verified line classifications. Leave them unknown when unsure.</p><div class="fun-choices">${['heart','head','life','fate'].map(key=>`<label>${key[0].toUpperCase()+key.slice(1)} line<select data-fun-line="${key}" aria-label="${key} line storytelling symbol"><option value="unknown">Unknown / leave out</option><option value="curved">Curved symbol</option><option value="straight">Straight symbol</option><option value="not-visible">Not visible / leave out</option></select></label>`).join('')}</div></details><button class="primary" id="make-fun-story">✦ Create my for-fun reading</button></div><p id="fun-status" role="status" class="fine"></p><div id="fun-output" hidden><span class="engine-badge" id="fun-mode"></span><h3 id="fun-title"></h3><p id="fun-basis" class="fine"></p><div id="fun-chapters" class="report-grid"></div><p class="fun-notice" id="fun-output-notice"></p><button class="outline" id="download-fun-story">↓ Download reading JSON</button></div>`;
q('#reading').after(section);const jump=document.createElement('button');jump.type='button';jump.className='outline';jump.textContent='✦ For Fun Reading';jump.onclick=()=>section.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});q('#export-report').before(jump);const style=document.createElement('style');style.textContent=`.fun-reading{background:radial-gradient(ellipse at 20% 20%,#63304744,transparent 65%),radial-gradient(ellipse at 90% 80%,#02543c44,transparent 65%),#12121d}.fun-intro{max-width:650px;font-size:12px;line-height:2;color:#c9c1b6}.fun-notice{padding:18px 22px;border:1px solid #d4ad6555;background:#c48f3110;color:#f0d29c;font-size:11px;line-height:1.9}.fun-notice small{font-size:10px;color:#b9cfb8}#fun-controls{margin-top:28px}.fun-theme{display:block;font-size:8px;letter-spacing:2px;color:#e0bd80}.fun-reading select{display:block;background:#152922;border:1px solid #c5a26866;color:#eddfc3;padding:13px;font:11px Manrope,Arial;margin-top:10px;max-width:100%;min-width:220px}.fun-manual{border-block:1px solid #d9b97830;padding:20px 0;margin:25px 0}.fun-manual summary{font-size:11px;cursor:pointer;color:#e3c28c}.fun-manual>p{font-size:10px;line-height:1.9;max-width:700px;color:#b5c6b4}.fun-choices{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px;margin-top:25px}.fun-choices label{font-size:11px;color:#cdbfa6}.fun-choices select{width:100%;min-width:0}#fun-output>h3{font:43px 'Cormorant Garamond',Georgia;color:#f1d4a5;margin:25px 0}#fun-output{margin-top:30px}#fun-chapters .story-icon{font-size:27px;color:#eac37c}#download-fun-story{margin-top:10px}@media(max-width:600px){.fun-choices{grid-template-columns:1fr}.fun-reading h2{font-size:43px}#fun-output>h3{font-size:34px}}`;document.head.append(style);
function reset(){version++;if(controller)controller.abort();controller=null;session=null;story=null;q('#fun-controls').hidden=true;q('#fun-output').hidden=true;q('#fun-empty').hidden=false;q('#fun-chapters').replaceChildren();q('#fun-title').textContent=q('#fun-basis').textContent=q('#fun-status').textContent=q('#fun-mode').textContent='';q('#make-fun-story').disabled=false;q('#make-fun-story').textContent='✦ Create my for-fun reading';q('#fun-theme').value='full';section.querySelectorAll('[data-fun-line]').forEach(s=>s.value='unknown')}
window.addEventListener('palma:clear',reset);window.addEventListener('palma:analysis',e=>{reset();session=e.detail;q('#fun-empty').hidden=true;q('#fun-controls').hidden=false;q('#fun-status').textContent='Your palm session is ready. Choose all topics or one focus for a for-fun symbolic reading.'});
function localStory(theme,choices){
const metaphor=choices.heart==='curved'?'Your curved-symbol choice is used here as a creative metaphor for warmth and openness.':choices.heart==='straight'?'Your straight-symbol choice is used here as a creative metaphor for steadiness and clear communication.':'No heart-line shape was selected; this is general symbolism, not an observed-line interpretation.';
const deck={relationships:{title:'Love & relationships',body:'The traditional heart-line theme invites reflection on affection, trust, and emotional connection. '+metaphor+' It does not establish your feelings or what another person will do.'},marriage:{title:'Marriage & commitment',body:'In this for-fun reading, partnership is imagined as a shared path of companionship, mutual choice, and growing together. No marriage or union line has been verified in your photographs. These themes do not establish whether you will marry or how a partnership will turn out.'},career:{title:'Career & ambitions',body:'The head and fate symbols become a playful lens for curiosity, creative effort, and finding direction. Imagine a chapter of exploring skills and possibilities, rather than a forecast of job offers, income, promotions, or your personality.'},future:{title:'Future possibilities',body:'The symbolic horizon stays open: new interests, changing plans, and opportunities you might choose to explore. Read this as a palmistry-inspired reflection on possibilities, not events your hand says will happen.'},timing:{title:'Marriage age & timing',body:'A palm photograph cannot establish a marriage age or date. No age, year, or timeline is calculated by this feature. Timing remains open in this entertainment reading.'},symbols:{title:'Your symbolic reflection',body:'Heart, head, life, and fate are creative symbols for connection, imagination, experience, and direction. Optional manual choices guide the wording; neither those choices nor image candidates verify predictions.'}};
const titles={full:'Your symbolic palmistry reading',relationships:'Love & relationships',marriage:'Marriage & commitment',career:'Career & ambitions',future:'Future possibilities'};const keys=theme==='full'?['relationships','marriage','career','future','timing']:[theme,'symbols',theme==='marriage'?'timing':theme==='future'?'relationships':'future'];const counts=Object.fromEntries(['left','right'].map(side=>[side,session.hands[side]?.features?.length||0]));return{mode:'local-story',title:titles[theme],notice,theme,choices,basis:`Your images contain ${counts.left} left-image and ${counts.right} right-image candidate segments. Named palm lines are unverified. This entertainment reading uses your selected topics and optional symbols, not a forecast from the photos.`,chapters:keys.map(key=>({...deck[key]}))}}
function show(result){story=result;q('#fun-title').textContent=result.title;q('#fun-basis').textContent=result.basis;q('#fun-output-notice').textContent=notice;q('#fun-mode').textContent=result.mode==='local-story'?'LOCAL SYMBOLIC READING · NO LIVE AI':result.mode==='local-story-fallback'?'LOCAL READING · LIVE AI UNAVAILABLE':result.mode.toUpperCase()+' · AI READING';q('#fun-chapters').replaceChildren();result.chapters.forEach((c,i)=>{const a=document.createElement('article'),icon=document.createElement('span'),h=document.createElement('h3'),p=document.createElement('p');icon.className='story-icon';icon.textContent=['♡','❧','✧','✦','◷'][i%5];h.textContent=c.title;p.textContent=c.body;a.append(icon,h,p);q('#fun-chapters').append(a)});q('#fun-output').hidden=false;q('#fun-status').textContent=result.provider_note||'Your symbolic reading is ready. For fun only.'}
q('#make-fun-story').onclick=async()=>{if(!session)return;const mine=version,theme=q('#fun-theme').value,choices=Object.fromEntries([...section.querySelectorAll('[data-fun-line]')].map(s=>[s.dataset.funLine,s.value]));q('#make-fun-story').disabled=true;q('#make-fun-story').textContent='✦ Preparing your reading…';q('#fun-status').textContent='Preparing your symbolic reading across the selected topics…';q('#fun-output').hidden=true;controller=new AbortController();const timeout=setTimeout(()=>controller?.abort(),90000);try{let result;if(session.backend&&session.scan_id){const response=await fetch('/api/fun-reading',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scan_id:session.scan_id,theme,choices}),signal:controller.signal});const data=await response.json();if(!response.ok||!data.ok)throw Error(data.error||'The story service could not respond.');result=data.story}else result=localStory(theme,choices);if(mine!==version)return;show(result)}catch(e){if(mine===version)q('#fun-status').textContent=e.name==='AbortError'?'Story creation timed out. Try again.':e.message}finally{clearTimeout(timeout);if(mine===version){q('#make-fun-story').disabled=false;q('#make-fun-story').textContent='✦ Create another for-fun reading';controller=null}}};
q('#download-fun-story').onclick=()=>{if(!story)return;const blob=new Blob([JSON.stringify({feature:'PALMA For Fun',...story,notice},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PALMA-For-Fun-Story.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};
})();
